// step - 1 add bootstrap cdn in to index.html

// step -2 React-Bootstrap  
/*
React Bootstrap
The most popular front-end framework, rebuilt for React.
React-Bootstrap replaces the Bootstrap JavaScript. Each component has been built 
from scratch as a true React component, without unneeded dependencies lik

npm install react-bootstrap bootstrap 

import Button from 'react-bootstrap/Button';

*/



import React from 'react'
import Alert from 'react-bootstrap/Alert';

function Boostrap() {
  return (
    <div>

        <Alert key="primary" variant="primary">
          This is a primary alert—check it out!
        </Alert>

        {
               [
        'primary',
        'secondary',
        'success',
        'danger',
        'warning',
        'info',
        'light',
        'dark'] 

        }
    
    </div>
  )
}

export default Boostrap
